from django.db import migrations, models
from django.db.models import Max

LEGACY = ("driver", "courier")


def to_transport(apps, schema_editor):
    """Old courier / driver accounts become the single "transport" role, and every transport
    account gets its driver record (number, name, phone) so it can open the driver app."""
    User = apps.get_model("bizsuite", "User")
    Driver = apps.get_model("bizsuite", "Driver")
    User.objects.filter(role__in=LEGACY).update(role="transport")
    linked = set(Driver._base_manager.exclude(user=None).values_list("user_id", flat=True))
    for u in User.objects.filter(role="transport").exclude(business=None).order_by("id"):
        if u.id in linked:
            continue
        top = Driver._base_manager.filter(business_id=u.business_id).aggregate(m=Max("number"))["m"] or 0
        name = (f"{u.first_name} {u.last_name}".strip() or u.username)[:200]
        Driver._base_manager.create(business_id=u.business_id, number=top + 1, name=name,
                              phone=(u.phone_number or "")[:20], user_id=u.id, is_active=u.is_active)


def to_driver(apps, schema_editor):
    apps.get_model("bizsuite", "User").objects.filter(role="transport").update(role="driver")


